import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA implementation of BatchNorm2d (fp16 I/O, float32 accumulation)
# ----------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <ATen/cuda/CUDAContext.h>

template <int TPB>
__global__ void bn_reduce_kernel(const __half* __restrict__ input,
                                 int N, int C, int H, int W,
                                 float* __restrict__ mean,
                                 float* __restrict__ var) {
    const int channel = blockIdx.x;
    const int total = N * H * W;
    float sum = 0.f;
    float sum2 = 0.f;
    for (int idx = threadIdx.x; idx < total; idx += TPB) {
        int n = idx / (H * W);
        int hw = idx % (H * W);
        int h = hw / W;
        int w = hw % W;
        int offset = ((n * C + channel) * H + h) * W + w;
        __half v = input[offset];
        float fv = __half2float(v);
        sum += fv;
        sum2 += fv * fv;
    }
    __shared__ float s_sum[TPB];
    __shared__ float s_sum2[TPB];
    s_sum[threadIdx.x] = sum;
    s_sum2[threadIdx.x] = sum2;
    __syncthreads();
#pragma unroll
    for (int stride = TPB / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sum2[threadIdx.x] += s_sum2[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        float m = s_sum[0] / total;
        float v = s_sum2[0] / total - m * m;
        mean[channel] = m;
        var[channel] = v;
    }
}

template <int TPB>
__global__ void bn_apply_kernel(const __half* __restrict__ input,
                                __half* __restrict__ output,
                                const float* __restrict__ mean,
                                const float* __restrict__ var,
                                const __half* __restrict__ weight,
                                const __half* __restrict__ bias,
                                int N, int C, int H, int W,
                                float eps) {
    const int idx = blockIdx.x * TPB + threadIdx.x;
    const int total = N * C * H * W;
    if (idx >= total) return;

    int tmp = idx;
    int w = tmp % W; tmp /= W;
    int h = tmp % H; tmp /= H;
    int c = tmp % C;
    // int n = tmp / C; // not needed

    float x = __half2float(input[idx]);
    float m = mean[c];
    float v = var[c];
    float g = __half2float(weight[c]);
    float b = __half2float(bias[c]);

    float norm = (x - m) * rsqrtf(v + eps);
    float y = norm * g + b;
    output[idx] = __float2half(y);
}

torch::Tensor bn_forward(torch::Tensor input,
                         torch::Tensor weight,
                         torch::Tensor bias,
                         torch::Tensor running_mean,
                         torch::Tensor running_var,
                         bool training,
                         double momentum,
                         double eps) {
    const int TPB = 256;
    auto device = input.device();
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto mean = torch::empty({C},
                             torch::dtype(torch::kFloat32).device(device));
    auto var  = torch::empty({C},
                             torch::dtype(torch::kFloat32).device(device));

    // ---- per‑channel mean / variance ----
    dim3 blocks(C);
    dim3 threads(TPB);
    bn_reduce_kernel<TPB><<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        N, C, H, W,
        mean.data_ptr<float>(),
        var.data_ptr<float>());
    cudaGetLastError();

    // ---- update running statistics (training) ----
    if (training) {
        running_mean.mul_(1.0 - momentum).add_(mean, momentum);
        running_var.mul_(1.0 - momentum).add_(var, momentum);
    } else {
        mean.copy_(running_mean);
        var.copy_(running_var);
    }

    // ---- apply normalization ----
    auto output = torch::empty_like(input);
    int total = N * C * H * W;
    int grid = (total + TPB - 1) / TPB;

    bn_apply_kernel<TPB><<<grid, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<const __half*>(bias.data_ptr()),
        N, C, H, W,
        static_cast<float>(eps));
    cudaGetLastError();

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("bn_forward", &bn_forward, "BatchNorm2d forward (CUDA)");
}
'''

# Compile the inline extension
bn_ext = load_inline(name='bn_ext',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['bn_forward'],
                     verbose=False)

# ----------------------------------------------------------------------
# PyTorch model that uses the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.eps = 1e-5
        self.momentum = 0.1

        # learnable parameters (fp16)
        self.weight = nn.Parameter(torch.ones(num_features,
                                               dtype=torch.float16))
        self.bias   = nn.Parameter(torch.zeros(num_features,
                                               dtype=torch.float16))

        # running statistics (float32, as in torch.nn.BatchNorm2d)
        self.register_buffer('running_mean',
                             torch.zeros(num_features, dtype=torch.float32))
        self.register_buffer('running_var',
                             torch.ones(num_features, dtype=torch.float32))

    def forward(self, x):
        if not x.is_cuda:
            x = x.cuda()
        out = bn_ext.bn_forward(x,
                                self.weight,
                                self.bias,
                                self.running_mean,
                                self.running_var,
                                self.training,
                                self.momentum,
                                self.eps)
        return out
